import rules from './rules';
import { i18n } from 'src/boot/i18n';

export default {
  methods: {
    async validateDate(value: string, mask: string) {
      const is_valid = await rules.date_with_mask(value, mask);
      return {
        is_valid: is_valid,
        input_error: 'invalid_input_date',
      };
    },
    async validateAmount(value: string) {
      const is_valid = await rules.amount(value);
      return {
        is_valid: is_valid,
        input_error: 'invalid_input_amount',
      };
    },

    async validateListOfValues(value: string, options: any) {
      const response = {
        is_valid: true,
        input_error: 'invalid_input_list_of_value',
      };

      // options empty
      if (!Array.isArray(options) || options.length == 0) {
        return Promise.resolve(response);
      }

      const Filtered = options.filter((f: any) => f.includes(value));
      if (Filtered.length == 0) {
        response['is_valid'] = false;
      }

      return Promise.resolve(response);
    },

    async validateFieldLength(value: string, field_length: string) {
      const response = {
        is_valid: true,
        input_error: 'invalid_field_length',
      };

      if (Number(field_length) !== 0 && value.length !== Number(field_length)) {
        response['is_valid'] = false;
      }

      return Promise.resolve(response);
    },

    async validateBannedKeywords(value: string, keywords: string) {
      const response = {
        is_valid: true,
        input_error: i18n.t('banned_keyword_error'),
      };

      try {
        keywords.split(',').forEach((keyword: string) => {
          if (value.includes(keyword)) {
            response['is_valid'] = false;
            response['input_error'] = response['input_error'].replace(
              '*keyword',
              keyword,
            );
          }
        });
      } catch (error) {
        logError(error);
      }

      return Promise.resolve(response);
    },

    async validateFieldArtikelNummber(value: string) {
      const response = {
        is_valid: true,
        input_error: 'invalid_item_number',
      };

      if (value.includes('_')) {
        response['is_valid'] = false;
      }

      if (value.length != 7) {
        response['is_valid'] = false;
        response['input_error'] = 'must_have_7_characters';
      }

      return Promise.resolve(response);
    },
  },
};
