import type { dynamicObj } from 'src/pages/assets';
const TOKENS = {
  '#': { pattern: '[\\d]' },
} as dynamicObj;

const KEYS = Object.keys(TOKENS);
KEYS.forEach((key) => {
  TOKENS[key].regex = new RegExp(TOKENS[key].pattern);
});

export default {
  /**
   * Rule: tests
   */

  //   Valid amount
  amount: function (value: string) {
    if(value === undefined || value === null || value === '') {
      return Promise.resolve(false);
    }
    value = String(value).replace(/\s/g, '');
    const isAmount = /^-?[0-9.,]+$/;
    return Promise.resolve(isAmount.test(value));
  },

  //   Valid amount
  date_with_mask(date: string, mask: string) {
    if (date === void 0 || date === null || date === '') {
      return false;
    }

    let is_valid = true;
    let valIndex = 0;

    for (let maskIndex = 0; maskIndex < mask.length; maskIndex++) {
      const maskDef = mask[maskIndex];
      const valChar = date[valIndex];

      if (typeof maskDef === 'string' && valChar === maskDef) {
        valIndex++;
        continue;
      }

      const c = TOKENS[maskDef];
      if (!c || !c.hasOwnProperty('regex') || !c.regex.test(valChar)) {
        is_valid = false;
        break;
      }
      valIndex++;
    }

    return Promise.resolve(is_valid);
  },
};
