import type { dynamicObj } from 'src/pages/assets';
import validation_mixin from 'src/validatior/validation_mixin';
import intUtils from 'src/utils/int';

export default class abstractValidator {
  protected mixins = Object.assign(validation_mixin.methods, intUtils.methods);

  async init(field_model: dynamicObj, field_config_model: dynamicObj) {
    return await this.validate(field_model, field_config_model);
  }

  /**
   * Implementation required
   */
  async validate(
    field_model: dynamicObj,
    field_config_model: dynamicObj,
  ): Promise<dynamicObj> {
    const response = {
      is_valid: false,
      input_error: '',
    };

    return Promise.resolve(response);
  }

  getFieldType(field_config_model: dynamicObj) {
    if (!field_config_model) {
      return '';
    }

    if (!field_config_model.field_type) {
      return '';
    }

    return String(field_config_model.field_type.toLowerCase());
  }
}
