import type { dynamicObj } from 'src/pages/assets';
import { isEmptyString } from 'src/utils/general';
import abstractValidator from './abstractValidator';
import { dateInput } from 'src/formBuilder/form_elements/formatter/TextInput/index';
// import { date } from 'quasar';

import {
  useFieldValuesSettingsStore,
  useFormBuilderStore,
} from 'src/store/main';
const list_of_values_store = useFieldValuesSettingsStore();
const form_builder_store = useFormBuilderStore();

export default class TextValidator extends abstractValidator {
  async validate(
    field_model: dynamicObj,
    field_config: dynamicObj,
  ): Promise<dynamicObj> {
    let is_valid = true;
    let input_error = '';

    const field_value = field_model.formatted_value;
    if (!field_value || field_value == '') {
      return Promise.resolve({
        is_valid,
        input_error,
      });
    }

    // validate Field Type rules
    const field_type = this.getFieldType(field_config);
    switch (field_type) {
      case 'date':
        const value = await dateInput.format(field_value);
        if (value == '' || value == null) {
          is_valid = false;
          input_error = 'invalid_input_date';
        }
        // logInfo('field_type', field_type, field_value);
        // if (!date.isValid(value)) {
        //   is_valid = false;
        //   input_error = 'invalid_input_date';
        // }
        break;
      // const mask = dateInput.getMask(form_builder_store.getDocDateFormat());
      // if (!(mask == '' || mask == null)) {
      //     ({is_valid, input_error} = await this.mixins.validateDate(field_value,mask));
      //     break;
      // }

      case 'amount':
        ({ is_valid, input_error } =
          await this.mixins.validateAmount(field_value));
        break;
    }

    // validate Other rules
    if (is_valid) {
      // validate list of values rule
      if (field_config.enforce_list_of_values) {
        ({ is_valid, input_error } = await this.mixins.validateListOfValues(
          field_value,
          list_of_values_store.getListOfValues(field_config.list_of_values),
        ));
      }

      // validate field length
      if (this.mixins.isInt(field_config.length)) {
        ({ is_valid, input_error } = await this.mixins.validateFieldLength(
          field_value,
          field_config.length,
        ));
      }

      if (!isEmptyString(field_config.banned_keywords)) {
        ({ is_valid, input_error } = await this.mixins.validateBannedKeywords(
          field_value,
          field_config.banned_keywords,
        ));
      }

      if (field_config.isFieldArtikelNummber) {
        ({ is_valid, input_error } =
          await this.mixins.validateFieldArtikelNummber(field_value));
      }
    }

    return Promise.resolve({
      is_valid,
      input_error,
    });
  }
}
